{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy allows actions on all resources ('Resource = "*"'), which can lead to privilege escalation or unintended access. Restricting the resource scope reduces the risk of misuse."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties",
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
    ]
  })
}",
  "fix_summary": "Restricted the IAM policy's 'Resource' field to target EC2 instances specifically, replacing the wildcard '*' with 'arn:aws:ec2:*:*:instance/*'. This limits the scope of the policy to reduce the risk of privilege escalation or unintended access."
}
